def skill(
    id: str, name: str, category_id: str, tool: str, stage: str,
    tags: list[str], description: str, url: str, *,
    sub_skill_id: str, sub_skill_label: str, core: bool = False,
    importance: int = 70, input_types: list[str] | None = None,
    output_types: list[str] | None = None,
) -> dict:
    category = next(item for item in AI_SKILL_CATEGORIES if item['id'] == category_id)
    return {
        'id': id, 'name': name, 'category_id': category_id,
        'category_label': category['label'], 'tool': tool, 'stage': stage,
        'description': description, 'tags': tags, 'examples': [url],
        'input_types': input_types or ['prompt', 'text', 'file'],
        'output_types': output_types or ['plan', 'draft', 'asset'],
        'difficulty': 2, 'importance': importance, 'is_core': core,
        'is_active': True, 'sub_skill_id': sub_skill_id,
        'sub_skill_label': sub_skill_label,
    }

